        "type": "string",
        "description": "The end date of the trip in the format 'YYYY-MM-DD'."
      },
      "seating_class": {
        "type": "string",
        "description": "The cabin seat option for the flight.",
        "enum": [
          "Economy",
          "Premium Economy",
          "Business"
        ],
        "default": "Economy"
      },
      "number_of_tickets": {
