      "airlines": {
        "type": "string",
        "description": "The preferred airline company for the trip. Use 'dontcare' if there is no preference.",
        "enum": [
          "United Airlines",
          "American Airlines",
          "Delta Airlines",
          "Southwest Airlines",
          "Alaska Airlines",
          "British Airways",
          "Air Canada",
          "Air France",
          "South African Airways",
          "LOT Polish Airlines",
          "LATAM Brasil",
          "dontcare"
        ],
        "default": "dontcare"
      }
    }
  }
}

{
  "name": "Hotels_4_SearchHotel",
