        ],
        "default": "Economy"
      },
      "number_of_tickets": {
        "type": "integer",
        "description": "The number of flight tickets required for the trip.",
        "default": 1
      },
      "airlines": {
        "type": "string",
        "description": "The preferred airline company for air transport services. Use 'dontcare' to indicate no preference.",
        "enum": [
          "United Airlines",
          "American Airlines",
          "Delta Airlines",
